    export const BoxBufferGeometry: typeof BoxGeometry;
    export type BoxBufferGeometry = BoxGeometry;
    /** r150 保留的 CapsuleGeometry 旧名称。 */
    export const CapsuleBufferGeometry: typeof CapsuleGeometry;
    export type CapsuleBufferGeometry = CapsuleGeometry;
