    export type CylinderBufferGeometry = CylinderGeometry;
    /** r150 保留的 DodecahedronGeometry 旧名称。 */
    export const DodecahedronBufferGeometry: typeof DodecahedronGeometry;
    export type DodecahedronBufferGeometry = DodecahedronGeometry;
    /** r150 保留的 ExtrudeGeometry 旧名称。 */
    export const ExtrudeBufferGeometry: typeof ExtrudeGeometry;
    export type ExtrudeBufferGeometry = ExtrudeGeometry;
    /** r150 保留的 IcosahedronGeometry 旧名称。 */
    export const IcosahedronBufferGeometry: typeof IcosahedronGeometry;
    export type IcosahedronBufferGeometry = IcosahedronGeometry;
    /** r150 保留的 LatheGeometry 旧名称。 */
    export const LatheBufferGeometry: typeof LatheGeometry;
