    /** r150 保留的 OctahedronGeometry 旧名称。 */
    export const OctahedronBufferGeometry: typeof OctahedronGeometry;
    export type OctahedronBufferGeometry = OctahedronGeometry;
    /** r150 保留的 PlaneGeometry 旧名称。 */
    export const PlaneBufferGeometry: typeof PlaneGeometry;
