    /** r150 保留的 RingGeometry 旧名称。 */
    export const RingBufferGeometry: typeof RingGeometry;
    export type RingBufferGeometry = RingGeometry;
    /** r150 保留的 ShapeGeometry 旧名称。 */
    export const ShapeBufferGeometry: typeof ShapeGeometry;
