    export const TorusKnotBufferGeometry: typeof TorusKnotGeometry;
    export type TorusKnotBufferGeometry = TorusKnotGeometry;
    /** r150 保留的 TubeGeometry 旧名称。 */
    export const TubeBufferGeometry: typeof TubeGeometry;
